/usr/bin/zsh -lc "cd /var/tmp/loop-bench/runs/05d31b170dc4/workspace/target && cat > src/transport/ws/listSessionsLimit.test.ts <<'EOF'
import {validateMessage} from './validation.js';

// @spec specs/hal-engine-conversation-list/spec.md#39
it('preserves non-negative integer list limits and refuses other supplied limits', () => {
  for (const limit of [0, 1, 200, 201]) {
    expect(validateMessage({type: 'list_sessions', limit})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit},
    });
  }
  for (const limit of [-1, 1.5, '10', null, true, NaN, Infinity]) {
    expect(validateMessage({type: 'list_sessions', limit})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
  }
});
EOF
timeout 300 npm test -- --runTestsByPath src/transport/ws/listSessionsLimit.test.ts --runInBand"
